from pathlib import Path
import pydantic
print('workspace import:', pydantic.__file__)
assert Path(pydantic.__file__).resolve().is_relative_to(Path.cwd().resolve())
import json
from pydantic import BaseModel, field_serializer
class Model(BaseModel):
    value:int
    @field_serializer("value")
    def serialize(self,value,info):return value+(info.context or {}).get("delta",0)
m=Model(value=3)
assert m.model_dump()=={"value":3}
print(m.model_dump(context={"delta":4}),m.model_dump_json(context={"delta":5}))
assert m.model_dump(context={"delta":4})=={"value":7}
assert json.loads(m.model_dump_json(context={"delta":5}))=={"value":8}
